'use client'
import { Package } from 'lucide-react'
import {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardContent,
} from '@/components/ui/card'
import {
  ResponsiveContainer,
  RadialBarChart,
  RadialBar,
  Legend,
  Tooltip,
} from 'recharts'
import { useGetDashboardSummary } from '@/lib/handleAllGetRequests'

export default function NewProductsChart() {
  const { data: summaryData, isLoading } = useGetDashboardSummary()
  const summary = summaryData?.data

  if (isLoading)
    return <div className="h-80 bg-gray-200 rounded animate-pulse"></div>

  // Define each bar's max for partial fill
  const radialData = summary
    ? [
        {
          name: 'This Day',
          value: summary.newProducts?.thisDay || 0,
          fill: '#4A3AFF',
          max: 10, // max value for day bar
        },
        {
          name: 'This Week',
          value: summary.newProducts?.thisWeek || 0,
          fill: '#005B50',
          max: 50, // max value for week bar
        },
        {
          name: 'This Month',
          value: summary.newProducts?.thisMonth || 0,
          fill: '#797068',
          max: 200, // max value for month bar
        },
      ]
    : []

  // Scale each bar individually for partial fill
  const scaledData = radialData.map((d) => ({
    ...d,
    scaledValue: (d.value / (d.max || 1)) * 100,
  }))

  // Custom tooltip to show actual values
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const data = radialData[payload[0].index]
      return (
        <div className="bg-white p-2 rounded shadow border">
          <p className="font-semibold">{data?.name}</p>
          <p>Value: {data?.value}</p>
        </div>
      )
    }
    return null
  }

  return (
    <Card className="h-full">
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Package className="h-5 w-5" />
          New Products Report
        </CardTitle>
        <CardDescription>
          Products added in different time periods
        </CardDescription>
      </CardHeader>
      <CardContent>
        <ResponsiveContainer width="100%" height={400}>
          <RadialBarChart
            cx="50%"
            cy="50%"
            innerRadius="10%"
            outerRadius="80%"
            barSize={15}
            data={scaledData}
            startAngle={180}
            endAngle={-180}
          >
            <Legend
              iconSize={10}
              layout="vertical"
              verticalAlign="top"
              align="right"
            />
            <RadialBar
              background
              dataKey="scaledValue"
              cornerRadius={10}
              fillOpacity={1}
            />
            <Tooltip content={<CustomTooltip />} />
          </RadialBarChart>
        </ResponsiveContainer>
      </CardContent>
    </Card>
  )
}
